HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AnviRoute</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f2eb;color:#262822;font:15px/1.55 'Segoe UI',system-ui,sans-serif}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}aside{background:#eeece3;border-right:1px solid #deded2;padding:34px 22px;display:flex;flex-direction:column;gap:36px}.brand{font-size:25px;font-weight:700;letter-spacing:-1px}.brand small{display:block;font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:400}.mark{background:#262822;color:#f5f2eb;border-radius:8px;display:inline-block;padding:0 10px;margin-right:6px}nav{display:grid;gap:8px}nav a{text-decoration:none;color:#74766b;padding:12px;border-radius:8px}nav a.current{background:#fffefa;color:#262822;font-weight:600}.aside-foot{margin-top:auto;font-size:12px;color:#74766b}main{width:100%;max-width:1320px;margin:auto;padding:38px 44px}h1{font-size:34px;letter-spacing:-1px;margin:0}h1 span{color:#69744d}p,small{color:#74766b}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.eyebrow{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#74766b}.badge{border:1px solid #d9dfca;background:#e9eddc;padding:7px 12px;border-radius:24px;color:#535f36;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fffefa;border:1px solid #deded2;border-radius:12px;padding:24px;margin-bottom:20px}h2{font-size:18px;margin:0 0 16px}input,select,button{font:inherit;border-radius:7px;padding:10px 12px;border:1px solid #deded2}input,select{background:#fffefa;color:inherit;width:100%;margin:6px 0 16px}input:focus,select:focus{outline:2px solid #69744d40;border-color:#69744d}label{font-size:12px;color:#53564b}button{cursor:pointer;background:#69744d;color:white;font-weight:500;margin:3px 6px 3px 0}button:hover{filter:brightness(.94)}button:disabled{opacity:.5;cursor:wait}button.secondary{background:transparent;color:#404535}code{color:#f5f2eb;background:#292c25;padding:15px;border-radius:8px;display:block;overflow-wrap:anywhere;font:13px/1.6 Consolas,monospace}.row{padding:14px 0;border-bottom:1px solid #deded2}.ok{color:#535f36}.bad{color:#a44e39}#notice{min-height:24px;white-space:pre-wrap}#events{max-height:320px;overflow:auto;font-size:13px}.flow{display:flex;gap:16px;justify-content:space-between;flex-wrap:wrap}.flow div{border:1px solid #deded2;padding:18px;border-radius:8px;flex:1;min-width:180px}.flow small{display:block;margin-top:6px}a{color:#59663e}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.stat{font-size:18px;font-weight:600;overflow-wrap:anywhere;margin-top:10px}.filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.filters select{width:180px}.filters input[type=search]{flex:1;min-width:150px}.filters label{white-space:nowrap}.filters input[type=checkbox]{width:auto;accent-color:#69744d}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th{color:#74766b;font-size:10px;text-transform:uppercase;letter-spacing:1px}th,td{padding:14px 10px;border-bottom:1px solid #deded2;vertical-align:top}td:last-child{min-width:230px;overflow-wrap:anywhere}.table-wrap{overflow:auto}.empty{padding:35px;text-align:center;color:#74766b}footer{font-size:12px;color:#74766b;margin-top:28px}[hidden]{display:none!important}@media(max-width:1000px){main{padding:26px}.shell{grid-template-columns:180px 1fr}aside{padding:28px 15px}.grid{grid-template-columns:1fr}.brand{font-size:22px}}@media(max-width:650px){.shell{display:block}aside{padding:18px;gap:15px;border-right:0}nav{display:flex;gap:2px}nav a{padding:8px}.aside-foot{display:none}main{padding:22px 16px}.stats{grid-template-columns:1fr;gap:0}header{align-items:start;gap:12px;flex-direction:column}h1{font-size:29px}}
</style></head><body><div class="shell"><aside><div class="brand"><span class="mark">a</span>AnviRoute<small>Your local routing desk</small></div><nav aria-label="Main"><a href="/">Overview</a><a href="/connections">Connections</a><a href="/logs">Error logs</a></nav><div class="aside-foot">● Local service<br><span id="local-address">127.0.0.1:20128</span><br><br>Standard library only</div></aside><main><header><div><div class="eyebrow">Workspace / <span id="page-name">Overview</span></div><h1 id="page-title">Your models, connected.</h1><p>A quiet place to keep Claude and your APIs in sync.</p></div><div class="badge">Local service · <span id="version"></span></div></header><p id="notice" role="status"></p>
<section id="overview"><div class="stats"><div class="card"><div class="eyebrow">Active profile</div><div id="profile-stat" class="stat">Add a connection</div><small>Saved once for your next session</small></div><div class="card"><div class="eyebrow">Selected model</div><div id="model-stat" class="stat">—</div><small>Passed automatically to Claude</small></div><div class="card"><div class="eyebrow">Connection check</div><div id="ready-stat" class="stat">Setup required</div><small>Authentication, model, and inference</small></div></div><div class="card"><h2>Connection path</h2><div class="flow"><div>Claude Code → AnviRoute<small id="client">Waiting for Claude</small></div><div>AnviRoute adapter<small id="adapter">Listening locally</small></div><div>AnviRoute → API / Kaggle<small id="upstream">Not checked</small></div></div><p>Second terminal, inside your project: <code>anviroute.cmd run claude</code></p></div>
<div class="grid"><div class="card"><div class="eyebrow">Terminal 1</div><h2>Keep the router running</h2><code id="start-command">anviroute.cmd start</code><p>Configure your API in the Connections page.</p></div><div class="card"><div class="eyebrow">Terminal 2 / Your project</div><h2>Start Claude Code</h2><code>anviroute.cmd run claude</code><p>No URL, key, or model prompts.</p></div></div><a href="/connections">Manage connections →</a></section><section id="connections"><div class="grid"><section><div class="card"><h2>API connections</h2><div id="providers"></div></div><div class="card"><h2>Add or edit a connection</h2><form id="form"><input id="id" type="hidden"><label>Name<input id="name" required placeholder="Kaggle Qwen"></label><label>API URL<input id="url" required placeholder="https://your-session.trycloudflare.com/v1"></label><label>API key<input id="key" type="password" autocomplete="off" placeholder="Blank keeps existing key when editing"></label><label>API format<select id="format"><option value="openai">OpenAI-compatible / Ollama</option><option value="anthropic">Anthropic Messages</option></select></label><label>Model (optional)<input id="model" placeholder="Leave blank to detect automatically"></label><button>Save connection</button><button type="button" class="secondary" id="clear">New connection</button></form><small><span id="credential-storage"></span>. Blank key keeps an existing saved key.</small></div></section>
<section><div class="card"><h2>Selected model</h2><p id="active">Select a connection</p><button id="check">Check API and model</button><button id="discover" class="secondary">Refresh models</button><select id="models"><option>No models loaded</option></select><button id="choose" class="secondary">Use selected model</button></div><div class="card"><h2>Session details</h2><p>Update the saved URL whenever a new Cloudflare tunnel starts. Check the connection after changing a profile.</p><a href="/logs">Open error logs →</a></div></section></div></section><section id="logs"><div class="card"><h2>Error logs</h2><p>Trace issues from Claude through the adapter to your API.</p><div class="filters"><select id="stage" aria-label="Filter stage"><option value="">All stages</option><option value="client">Claude → AnviRoute</option><option value="adapter">Adapter</option><option value="upstream">AnviRoute → API</option></select><input id="search" type="search" placeholder="Search logs…" aria-label="Search logs"><label><input id="errors-only" type="checkbox" checked> Errors only</label><button class="secondary" id="export">Export JSON</button></div><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Stage</th><th>Status</th><th>Profile</th><th>Message</th></tr></thead><tbody id="log-rows"></tbody></table></div><div class="empty" id="empty">No errors recorded. Your routing desk is quiet.</div></div><div class="card"><h2>Find the right fix</h2><p><b>Claude → AnviRoute:</b> keep the service terminal running and start Claude with the AnviRoute command.</p><p><b>Adapter:</b> inspect the message for unsupported request or response content.</p><p><b>AnviRoute → API:</b> check Kaggle, tunnel URL, API key, model availability, and rate limits. Save changes and check again.</p><small>Up to 500 recent events. Rotating logs use about 768 KB maximum. Prompts, replies, and credentials are excluded.</small></div></section><footer>AnviRoute · Local by default. Yours to configure.</footer></main></div><script>
const token=__TOKEN__;let state={providers:[]};const $=id=>document.getElementById(id);function msg(t,bad=false){$('notice').textContent=t;$('notice').className=bad?'bad':'ok'}
async function api(path,data){let r=await fetch('/control/'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function button(label,action){let b=document.createElement('button');b.textContent=label;b.className='secondary';b.onclick=()=>action().catch(e=>msg(e.message,true));return b}
async function refresh(){try{state=await api('status');$('version').textContent=state.version;$('local-address').textContent=state.address.replace('http://','');$('client').textContent=state.client_seen?'Request received · '+state.client_seen:'Waiting for Claude';$('adapter').textContent=state.address;$('upstream').textContent=state.upstream||'Not checked';let a=state.providers.find(p=>p.id===state.active);$('active').textContent=a?a.name+' · '+(a.model||'Model not selected'):'Select a connection';$('providers').replaceChildren();for(let p of state.providers){let r=document.createElement('div');r.className='row';let t=document.createElement('p');t.textContent=(p.id===state.active?'● ':'')+p.name+' · '+(p.model||'Auto-detect');r.append(t,button('Activate',async()=>{await api('activate',{id:p.id});await refresh()}),button('Edit',async()=>{for(let k of ['id','name','url','model'])$(k).value=p[k]||'';$('format').value=p.format;$('key').value=''}),button('Remove',async()=>{if(confirm('Remove '+p.name+'?')){await api('remove',{id:p.id});await refresh()}}));$('providers').append(r)}$('profile-stat').textContent=a?a.name:'Add a connection';$('model-stat').textContent=state.model||'—';$('ready-stat').textContent=state.ready?'Connection verified':'Check required';$('credential-storage').textContent=state.credential_storage;$('start-command').textContent='anviroute.cmd start'+(a?' --modelname '+JSON.stringify(a.name):'');renderLogs()}catch(e){msg(e.message,true)}}
$('form').onsubmit=async e=>{e.preventDefault();try{await api('save',{id:$('id').value,name:$('name').value,url:$('url').value,key:$('key').value,model:$('model').value,format:$('format').value});$('key').value='';msg('Saved. Activate the connection and check it.');await refresh()}catch(e){msg(e.message,true)}};
$('clear').onclick=()=>{$('form').reset();$('id').value=''};
$('check').onclick=async()=>{msg('Checking API and inference. A cold model may take time…');try{let r=await api('check',{});msg(r.message);await refresh()}catch(e){msg(e.message,true);await refresh()}};
$('discover').onclick=async()=>{try{let r=await api('models',{});$('models').replaceChildren();for(let m of r.models){let o=document.createElement('option');o.value=o.textContent=m;$('models').append(o)}msg('Models refreshed')}catch(e){msg(e.message,true)}};
$('choose').onclick=async()=>{try{await api('model',{model:$('models').value});msg('Model selected. New requests use it.');await refresh()}catch(e){msg(e.message,true)}};
const page=location.pathname==='/logs'?'logs':location.pathname==='/connections'?'connections':'overview';
for(let p of ['overview','connections','logs'])$(p).hidden=p!==page;
$('page-name').textContent=page[0].toUpperCase()+page.slice(1);if(page==='logs')$('page-title').textContent='A clearer view of errors.';if(page==='connections')$('page-title').textContent='A home for every API.';
document.querySelector('nav a[href="'+location.pathname+'"]').classList.add('current');
function filtered(){return [...(state.events||[])].reverse().filter(e=>(!$('errors-only').checked||!e.ok)&&(!$('stage').value||e.stage===$('stage').value)&&JSON.stringify(e).toLowerCase().includes($('search').value.toLowerCase()))}
function renderLogs(){const list=filtered();$('log-rows').replaceChildren();for(let e of list){let tr=document.createElement('tr');for(let value of [e.time,e.stage,e.status??(e.ok?'OK':'Error'),e.profile||'—',e.message]){let td=document.createElement('td');td.textContent=value;td.className=e.ok?'':'bad';tr.append(td)}$('log-rows').append(tr)}$('empty').hidden=!!list.length}
for(let id of ['stage','search','errors-only'])$(id).oninput=renderLogs;
$('export').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify(filtered(),null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='anviroute-events.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
refresh();setInterval(refresh,4000);
</script></body></html>'''
